{
  "kc_id": "KC_CLU_HIER_005",
  "canonical_name": "MAX (Complete Linkage)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "direct_definition",
    "text": "In the MAX (complete linkage) version of hierarchical clustering, the proximity between two clusters is defined as the maximum distance (or minimum similarity) between any two points in the two different clusters.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "definition_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "direct_scope",
    "text": "This method favors globular shapes and is less susceptible to noise and outliers, although it can break large clusters. In graph terminology, a group of points is not considered a cluster until all points within it are completely linked, forming a clique.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "definition_lane"
    ],
    "abstention_reason": ""
  }
}

