{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "SSE, also known as scatter, is an objective function used to measure clustering quality, calculated as the total sum of the squared Euclidean distances from each data point to its closest centroid.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used to compare clustering results, where a lower SSE indicates better clustering and that the centroids are a better representation of the points in their clusters.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
      "context_lane",
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_EVAL_BASIC_001",
  "canonical_name": "Confusion Matrix",
  "definition": {
    "status": "grounded",
    "grounding_mode": "direct_definition",
    "text": "A confusion matrix is a table that summarizes the comparison of predicted labels against the true labels of instances to evaluate the performance of a classifier.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "definition_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "It is a basic approach for representing a classifier's performance on a test set and can be used to estimate evaluation measures on a test set when combined with an estimate of the test data skew and the TPR and TNR on a validation set.",
    "supporting_evidence_ids": [
      "E4",
      "E8"
    ],
    "supporting_lanes": [
      "scope_lane",
      "context_lane"
    ],
    "abstention_reason": ""
